import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"欢迎来到 Sync Engine 文档","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/usage/welcome.md","filePath":"zh-Hans/usage/welcome.md","lastUpdated":1795267545000}`),a={name:`zh-Hans/usage/welcome.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="欢迎来到-sync-engine-文档" tabindex="-1">欢迎来到 Sync Engine 文档 <a class="header-anchor" href="#欢迎来到-sync-engine-文档" aria-label="Permalink to “欢迎来到 Sync Engine 文档”">​</a></h1><blockquote><p>一个同步插件，也是一个平台：用模块扩展它，不需要 fork。</p></blockquote><p>感谢你选择 Sync Engine。我们希望凭借技术创新与持续迭代，成为 Obsidian 生态中最快、最通用的免费同步插件。你每一次使用 Sync Engine，都是对它工程严谨性的认可。</p><p>Sync Engine 文档分为三个部分：<em>用法</em>、<a href="./../development/develop-a-module"><em>开发</em></a> 和 <a href="./../deep-dive/architecture"><em>深入解析</em></a>，各部分服务于自己的目标：</p><ul><li><em>用法</em>：用所有人都能读懂的语言，讲解 Sync Engine 的使用方式，以及用户最关心的内容（可靠性、安全性与数据隐私）。适合普通用户熟悉和探索 Sync Engine。</li><li><em>开发</em>：详述 Sync Engine 的模块契约与 SDK API。适合希望用自己的模块扩展 Sync Engine 的技术用户。</li><li><em>深入解析</em>：带你了解 Sync Engine 与官方模块的每一个技术细节。适合好奇 Sync Engine 如何实现功能的学习者，以及希望验证 Sync Engine 各项声明的审计者。</li></ul><p>当前是<em>用法</em>部分，你可能对以下内容感兴趣：</p><ul><li><a href="./why-sync-engine">为什么选择 Sync Engine</a>：Sync Engine 与其他同步插件的区别，以及如何开始你的第一次同步。</li><li><a href="./settings">设置</a>：Sync Engine 每个设置项的含义。</li><li><a href="./benchmark">基准测试</a>：用真实数据看看 Sync Engine 与其他插件的对比。</li><li><a href="./security">安全</a>、<a href="./permissions">权限</a>：Sync Engine 的核心声明，用可验证的证据建立信任。</li><li><a href="./../development/develop-a-module">开发模块</a>：学习如何开发一个 Sync Engine 模块。</li></ul><p>如果发现 Sync Engine 的 bug，请在 <a href="https://github.com/hesprs/sync-engine/issues" target="_blank" rel="noreferrer">Sync Engine 的 GitHub 仓库</a> 提交 issue。如有疑问，请在 <a href="https://github.com/hesprs/sync-engine/discussions" target="_blank" rel="noreferrer">discussions</a> 发起讨论。</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};